"""Parcours navigateur de la gestion de projet Kairos (deux membres, temps réel). Usage : python3 tests/pm_browser_e2e.py http://localhost:8950"""
import asyncio, sys, random, datetime
from playwright.async_api import async_playwright
B = sys.argv[1]; R = random.randint(1000, 9999); out = []
def ok(c, m): print(("PASS " if c else "FAIL ") + m); out.append(c)
async def unlock(pg):
    await pg.goto(B + "/"); await pg.wait_for_selector("#mp", timeout=15000)
    await pg.fill("#mp", "Kairos-Maitre-2026!"); await pg.fill("#mp2", "Kairos-Maitre-2026!"); await pg.click("#lockBtn")
    await pg.wait_for_selector("#nav a", timeout=30000)
async def main():
  async with async_playwright() as p:
    b = await p.chromium.launch()
    ctxA = await b.new_context(viewport={"width": 1440, "height": 900}); A = await ctxA.new_page(); errs = []
    A.on("pageerror", lambda e: errs.append(str(e)[:150]))
    await unlock(A)
    ok(await A.locator("#nav a[href='#/projects']").count() == 1, "entrée « Projets » dans la navigation de Kairos")
    await A.click("#nav a[href='#/projects']"); await A.wait_for_selector("[data-pm-form='register']")
    f = A.locator("[data-pm-form='register']")
    await f.locator("[name=name]").fill("Amina Benali"); await f.locator("[name=handle]").fill(f"amina{R}"); await f.locator("[name=password]").fill("motdepasse1"); await f.locator("button").click()
    await A.wait_for_selector("[data-pm-form='createTeam']"); await A.fill("[data-pm-form='createTeam'] [name=name]", "Agence Atlas"); await A.click("[data-pm-form='createTeam'] button")
    await A.wait_for_selector(".pm-side"); await A.wait_for_timeout(500)
    ok("Tableau de bord" in await A.inner_text(".pm-main"), "espace de travail créé : tableau de bord affiché")
    # nouvel espace + liste via les menus
    await A.click("[data-pm='newSpace']"); await A.fill("dialog [name=v]", "Clients"); await A.click("dialog .btn.primary"); await A.wait_for_timeout(900)
    await A.click(".pm-space-head:has-text('Clients') [data-pm='spaceMenu']"); await A.click(".pm-menu [data-v='list']")
    await A.fill("dialog [name=v]", "Refonte du site"); await A.click("dialog .btn.primary"); await A.wait_for_timeout(1200)
    ok("Refonte du site" in await A.inner_text(".pm-title h1"), "liste créée dans l’espace « Clients » et ouverte")
    for title in ["Charte graphique", "Maquette accueil", "Intégration", "Mise en ligne"]:
        await A.fill(".pm-group[data-group='todo'] .pm-quick input", title); await A.press(".pm-group[data-group='todo'] .pm-quick input", "Enter"); await A.wait_for_timeout(350)
    ok(await A.locator(".pm-row").count() == 4, "4 tâches ajoutées en saisie rapide (vue Liste)")
    # statut via menu
    await A.click(".pm-row:has-text('Charte graphique') [data-pm='status']"); await A.click(".pm-menu [data-v='doing']"); await A.wait_for_timeout(600)
    ok(await A.locator(".pm-group[data-group='doing'] .pm-row:has-text('Charte graphique')").count() == 1, "changement de statut depuis la liste")
    # détail : responsables, priorité, dates, description, sous-tâche, checklist, commentaire, temps
    await A.click(".pm-row:has-text('Maquette accueil') .pm-name"); await A.wait_for_selector(".pm-d-title")
    await A.click("[data-pm='dPriority']"); await A.click(".pm-menu [data-v='1']"); await A.wait_for_timeout(500)
    today = datetime.date.today(); d = lambda n: (today + datetime.timedelta(days=n)).isoformat()
    await A.fill("[data-pm-change='dStart']", d(1)); await A.dispatch_event("[data-pm-change='dStart']", "change"); await A.wait_for_timeout(500)
    await A.fill("[data-pm-change='dDue']", d(4)); await A.dispatch_event("[data-pm-change='dDue']", "change"); await A.wait_for_timeout(500)
    await A.click("[data-pm='descEdit']"); await A.fill("[data-key='desc']", "## Objectif\n- [ ] Hero avec **photo**\n- [x] Menu"); await A.click("[data-pm='descDone']"); await A.wait_for_timeout(600)
    ok(await A.locator(".pm-desc .pm-md h4").count() == 1 and await A.locator(".pm-desc .pm-md strong").count() == 1, "description en Markdown (titre, gras, cases)")
    await A.fill("[data-pm-form='subtask'] input", "Version mobile"); await A.press("[data-pm-form='subtask'] input", "Enter"); await A.wait_for_timeout(600)
    await A.fill("[data-pm-form='check'] input", "Valider les couleurs"); await A.press("[data-pm-form='check'] input", "Enter"); await A.wait_for_timeout(600)
    await A.fill("[data-pm-form-input='tag']", "design"); await A.press("[data-pm-form-input='tag']", "Enter"); await A.wait_for_timeout(600)
    await A.click("[data-pm='startTimer']"); await A.wait_for_timeout(700)
    ok(await A.locator(".pm-running").count() == 1, "chronomètre lancé, visible dans la barre latérale")
    await A.click("[data-pm='stopTimer'] >> nth=0"); await A.wait_for_timeout(700)
    await A.fill(".pm-comment-form textarea", "Première version prête, à relire."); await A.click(".pm-comment-form button"); await A.wait_for_timeout(700)
    body = await A.inner_text(".pm-d-body")
    ok("Version mobile" in body and "Valider les couleurs" in body and "Première version prête" in body and "Urgente" in body, "détail : priorité, sous-tâche, checklist, étiquette, commentaire")
    await A.screenshot(path="/tmp/pm_detail.png")
    await A.click("[data-pm='closeDetail']")
    row = await A.inner_text(".pm-row:has-text('Maquette accueil')")
    ok("1/1" not in row and "0/1" in row and "design" in row, "la ligne affiche sous-tâches, checklist et étiquette")
    # dépendance + blocage
    await A.click(".pm-row:has-text('Mise en ligne') .pm-name"); await A.wait_for_selector("[data-pm='depAdd']")
    await A.click("[data-pm='depAdd']"); await A.click(".pm-menu button:has-text('Intégration')"); await A.wait_for_timeout(600)
    await A.click("[data-pm='dClose']"); await A.wait_for_selector("dialog[open]")
    ok("bloquée" in (await A.inner_text("dialog[open]")).lower(), "terminer une tâche bloquée : confirmation demandée")
    await A.click("dialog[open] [data-act='close'], dialog[open] .btn:not(.primary):not(.danger)"); await A.wait_for_timeout(300); await A.click("[data-pm='closeDetail']")
    # vues
    await A.click("[data-pm='mode'][data-id='board']"); await A.wait_for_timeout(500)
    ok(await A.locator(".pm-col").count() == 4 and await A.locator(".pm-card").count() == 4, "vue Tableau : 4 colonnes (statuts), 4 cartes")
    await A.drag_and_drop(".pm-card:has-text('Intégration')", ".pm-col[data-group='review']"); await A.wait_for_timeout(900)
    ok(await A.locator(".pm-col[data-group='review'] .pm-card:has-text('Intégration')").count() == 1, "glisser-déposer d’une carte vers « En revue »")
    await A.screenshot(path="/tmp/pm_board.png")
    await A.click("[data-pm='mode'][data-id='table']"); await A.wait_for_timeout(500)
    ok(await A.locator(".pm-table tbody tr").count() >= 4, "vue Données (tableur éditable)")
    await A.click("[data-pm='mode'][data-id='calendar']"); await A.wait_for_timeout(500)
    ok(await A.locator(f".pm-cal-day[data-drop-day='{d(4)}'] .pm-cal-item:has-text('Maquette accueil')").count() == 1, "vue Calendrier : tâche au jour de son échéance")
    await A.click("[data-pm='mode'][data-id='gantt']"); await A.wait_for_timeout(600)
    ok(await A.locator(".pm-bar").count() >= 1, "vue Gantt : barre de la tâche datée")
    await A.screenshot(path="/tmp/pm_gantt.png")
    await A.click("[data-pm='mode'][data-id='list']")
    # statuts personnalisés
    await A.click("[data-pm='listSettings']"); await A.wait_for_selector("dialog[open] .pm-st-row")
    await A.click("dialog[open] [data-add]"); await A.wait_for_timeout(200)
    await A.locator("dialog[open] [data-k='name']").nth(3).fill("Validation client"); await A.click("dialog[open] button.primary"); await A.wait_for_timeout(1000)
    ok(await A.locator(".pm-group[data-group='validation_client']").count() == 1, "statut personnalisé « Validation client » ajouté")
    # invitation + second membre
    await A.goto(B + "/#/projects/settings"); await A.wait_for_selector("[data-pm='invite']"); await A.click("[data-pm='invite']"); await A.wait_for_selector("#pmInvite .mono")
    code = (await A.inner_text("#pmInvite .mono")).strip()
    ctxB = await b.new_context(viewport={"width": 1280, "height": 860}); Bp = await ctxB.new_page(); Bp.on("pageerror", lambda e: errs.append(str(e)[:150]))
    await unlock(Bp); await Bp.goto(B + "/#/projects"); await Bp.wait_for_selector("[data-pm-form='register']")
    f = Bp.locator("[data-pm-form='register']"); await f.locator("[name=name]").fill("Karim Alaoui"); await f.locator("[name=handle]").fill(f"karim{R}"); await f.locator("[name=password]").fill("motdepasse1"); await f.locator("button").click()
    await Bp.wait_for_selector("[data-pm-form='join']"); await Bp.fill("[data-pm-form='join'] [name=code]", code); await Bp.click("[data-pm-form='join'] button")
    await Bp.wait_for_selector(".pm-side"); await Bp.wait_for_timeout(500)
    ok("Clients" in await Bp.inner_text(".pm-side"), "Karim rejoint l’équipe avec le code et voit l’espace « Clients »")
    await Bp.click(".pm-list:has-text('Refonte du site')"); await Bp.wait_for_selector(".pm-row")
    # assignation par Amina → boîte de réception de Karim ; temps réel
    await A.evaluate("location.hash = '#/projects'"); await A.wait_for_timeout(1200); await A.screenshot(path="/tmp/pm_back.png")
    await A.click(".pm-list:has-text('Refonte du site')", timeout=8000); await A.wait_for_selector(".pm-row")
    await A.click(".pm-row:has-text('Charte graphique') [data-pm='assignees']"); await A.click(f".pm-menu button:has-text('Karim')"); await A.click(".pm-menu [data-v='__ok']"); await A.wait_for_timeout(1500)
    ok(await Bp.locator(".pm-row:has-text('Charte graphique') .pm-av").count() >= 1, "temps réel : Karim voit l’assignation sans recharger")
    await A.fill(".pm-group[data-group='todo'] .pm-quick input", "Photos du restaurant"); await A.press(".pm-group[data-group='todo'] .pm-quick input", "Enter"); await A.wait_for_timeout(1500)
    ok(await Bp.locator(".pm-row:has-text('Photos du restaurant')").count() == 1, "temps réel : la nouvelle tâche d’Amina apparaît chez Karim")
    await A.click("[data-pm='chat']"); await A.fill("#pmChat input", "On boucle la charte demain ?"); await A.click("#pmChat button.primary"); await A.wait_for_timeout(1000)
    await Bp.click("[data-pm='chat']"); await Bp.wait_for_timeout(400)
    ok("On boucle la charte demain" in await Bp.inner_text("#pmChat"), "discussion d’équipe en direct dans la liste")
    await Bp.click(".pm-link:has-text('Boîte de réception')"); await Bp.wait_for_timeout(700)
    ok("vous a assigné" in await Bp.inner_text(".pm-main"), "boîte de réception de Karim : assignation")
    await Bp.click(".pm-link:has-text('Mes tâches')"); await Bp.wait_for_timeout(700)
    ok(await Bp.locator(".pm-row:has-text('Charte graphique')").count() == 1, "« Mes tâches » de Karim")
    await A.click(".pm-link:has-text('Tableau de bord')"); await A.wait_for_timeout(900)
    ok("Charge de l’équipe" in await A.inner_text(".pm-main") and await A.locator(".pm-kpi").count() == 6, "tableau de bord : indicateurs et charge de l’équipe")
    await A.screenshot(path="/tmp/pm_dashboard.png", full_page=True)
    await A.click(".pm-link:has-text('Objectifs')"); await A.wait_for_timeout(500); await A.click("[data-pm='goalEdit']")
    await A.fill("dialog[open] [name=name]", "Lancer le nouveau site"); await A.click("dialog[open] [data-add]"); await A.wait_for_timeout(200)
    await A.locator("dialog[open] [data-k='target']").fill("200"); await A.click("dialog[open] button.primary"); await A.wait_for_timeout(900)
    ok(await A.locator(".pm-goal:has-text('Lancer le nouveau site')").count() == 1, "objectif créé avec une cible chiffrée")
    ok(not errs, "aucune erreur JavaScript" + (f" : {errs}" if errs else ""))
    print(f"\n{sum(out)}/{len(out)} vérifications réussies")
    await b.close()
asyncio.run(main())
